        "Recorrer Castello Estense, Palazzo Schifanoia y la exposición de Palazzo dei Diamanti en Ferrara.",
        "Ver el David, subir a la Cupola del Brunelleschi y dedicar 2.5–3 horas a Gallerie degli Uffizi en Firenze.",
