          "am": "Presentarse en el *Aeropuerto Internacional de la Ciudad de México (MEX)* la noche del *miércoles 25 de noviembre* 3 horas antes (*9:05 PM*). Abordar el vuelo de *Iberia* con salida a las *00:05 hrs del jueves 26* hacia *Milano Malpensa (MXP)*. Duración total del viaje: *15 h 05 min*.",
          "pm": "Realizar la conexión en el *Aeropuerto de Madrid-Barajas (MAD)*. Tiempo de escala: *2 h 45 min*. Abordar el vuelo de continuación hacia *Milano*.",
          "night": "Llegada al *Aeropuerto Milano Malpensa (MXP)* a las *22:10 hrs*. Desde la *Terminal 1*, tomar el autobús gratuito hacia la *Terminal 2* y caminar al hotel *Moxy Milano Malpensa Airport* para realizar el check-in.",
          "mobility": "Traslado interno *T1 → T2*: Utiliza el autobús gratuito del aeropuerto *(10-15 min de trayecto)*. Sigue los letreros de conexión entre terminales y toma el acceso peatonal directo al hotel (5 min a pie). Confirma tu terminal exacta de llegada y los horarios nocturnos del autobús.",
