          "places": [
            "emilia-vitale",
            "emilia-galla"
          ],
          "am": "*1.* Desayunar y caminar desde *HouSmart Milazzo 5* hasta *Bologna Centrale*. Tomar el tren *Regionale* hacia *Ravenna* (aprox. 1 h 15 min; consultar horario previsto).\n*2.* Desde la estación de *Ravenna*, caminar 8–10 min hasta la *Basilica di Sant’Apollinare Nuovo*. Visitar sus mosaicos bizantinos (30–40 min). Entrada incluida en el billete combinado.\n*3.* Caminar hasta la *Tomba di Dante* (5–10 min) y visitar el sepulcro de *Dante Alighieri*. Acceso gratuito (10–15 min).\n*4.* Visitar la cercana *Basilica di San Francesco* y contemplar su cripta inundada. Acceso gratuito; iluminación de la cripta €1 (≈ $20 MXN). Realizar la visita antes de las 12:00.\n*5.* Caminar hasta el *Battistero Neoniano* (5–10 min) y contemplar los mosaicos de su cúpula (15–20 min). Entrada incluida en el billete combinado; reservar franja horaria.\n*6.* Visitar el *Museo Arcivescovile* y la *Cappella di Sant’Andrea*, situados junto al baptisterio. Recorrer sus salas y contemplar los mosaicos de la capilla (30–40 min). Entrada incluida; reservar franja horaria.",
          "pm": "*1.* Almorzar en el centro histórico de *Ravenna* (45–60 min). Probar alguna especialidad local, como *cappelletti al ragù* o *piadina romagnola*.\n*2.* Caminar hasta la *Basilica di San Vitale* (10–15 min) y recorrer su interior, prestando especial atención a los mosaicos de *Giustiniano* y *Teodora*. Duración: 45–60 min. Entrada incluida en el billete combinado.\n*3.* Visitar el vecino *Mausoleo di Galla Placidia* y contemplar sus mosaicos, especialmente la bóveda estrellada. Duración: 15–20 min. Entrada incluida; reservar franja horaria.\n*4.* Disfrutar del tiempo restante paseando por el centro histórico o tomando un café antes de regresar a la estación.",
          "night": "*1.* Caminar desde *San Vitale* o el centro histórico hasta la estación *Ravenna* (15–20 min). Llegar con al menos 15 min de anticipación.\n*2.* Tomar el tren *Regionale* de regreso a *Bologna Centrale* (salida prevista 17:43; confirmar horario definitivo).\n*3.* Cenar cerca de *Bologna Centrale* o del alojamiento y regresar a *HouSmart Milazzo 5* para descansar.",
          "mobility": "• *Bologna → Ravenna:* Tren *Regionale* desde *Bologna Centrale* hasta *Ravenna* (aprox. 1 h 15 min). Confirmar horario de salida.\n• *Estación → Sant’Apollinare Nuovo:* Caminar 8–10 min.\n• *Sant’Apollinare Nuovo → Zona de Dante:* Caminar 5–10 min hasta *Tomba di Dante* y *Basilica di San Francesco*.\n• *San Francesco → Battistero Neoniano:* Caminar 5–10 min. El *Museo Arcivescovile* está junto al baptisterio.\n• *Museo Arcivescovile → San Vitale:* Caminar 10–15 min.\n• *San Vitale → Galla Placidia:* Ambos monumentos se encuentran en el mismo complejo, a pocos minutos a pie.\n• *San Vitale → Estación:* Caminar 15–20 min hasta *Ravenna*.\n• *Ravenna → Bologna:* Tren *Regionale* previsto a las 17:43. Confirmar horario y posibles cambios de servicio.\n• *Transporte local:* Todo el recorrido monumental se realiza a pie, sin necesidad de autobuses.",
          "spend": null,
          "note": "• *Billete combinado:* Comprar el *Itinerario 5 monumenti* (€14.50 ≈ $296 MXN). Válido 7 días, con una entrada por monumento. Incluye *Sant’Apollinare Nuovo*, *San Vitale*, *Galla Placidia*, *Battistero Neoniano* y *Museo Arcivescovile / Cappella di Sant’Andrea*.\n• *Reservas:* Comprar online y seleccionar las franjas obligatorias, especialmente para *Galla Placidia*, *Battistero Neoniano* y *Museo Arcivescovile*.\n• *Horarios de invierno:* Confirmar el calendario aplicable al 30 de noviembre de 2026. No utilizar los horarios de verano, vigentes hasta el 1 de noviembre.\n• *Último acceso:* Prever terminar los monumentos antes de las 17:00, sujeto a confirmación de los horarios de invierno.\n• *Orden de visitas:* Ajustar la secuencia a las franjas reservadas, manteniendo el regreso en tren previsto a las 17:43.",
