          "am": "*1.* Desayunar en *Bologna* y tomar el tren *Regionale* desde *Bologna Centrale* hasta *Modena*. Caminar 8–10 min desde la estación hasta el *Museo Enzo Ferrari*.\n*2.* Visitar el *Museo Enzo Ferrari* desde las 09:30. Recorrer la exposición de automóviles, la casa natal y el antiguo taller familiar de *Enzo Ferrari*. Duración: 1.5–2 h. Entrada €27 (≈ $551 MXN); compra anticipada recomendable.\n*3.* Visitar la exposición temporal *The Greatest Hits – Music Legends and their Ferraris*, incluida en el museo. Buscar los vehículos de *Eric Clapton*, *J Balvin* y otros músicos. Exposición programada hasta febrero de 2027.\n*4.* Caminar 15–20 min hacia el centro histórico y llegar a *Piazza Grande*, conjunto Patrimonio Mundial de la UNESCO. Contemplar la fachada del *Duomo di Modena*, sus relieves de *Wiligelmo* y la *Torre Ghirlandina*.\n*5.* Visitar el interior del *Duomo di Modena*, incluyendo la cripta de *San Geminiano* y las esculturas de *Guido Mazzoni*. Duración: 30–40 min. Acceso principal gratuito, fuera del culto. Presbiterio elevado y sacristía opcionales (€3 ≈ $61 MXN).",
          "pm": "*1.* Caminar 3–5 min hasta el *Mercato Albinelli* (Via Luigi Albinelli 13). Recorrer sus puestos de productos regionales y almorzar. Buscar *Parmigiano Reggiano*, *Aceto Balsamico Tradizionale di Modena*, *tigelle* y *gnocco fritto*. Acceso gratuito; compras y comida aparte. Prever 45–60 min.\n*2.* Regresar a *Piazza Grande* y visitar las *Sale Storiche del Palazzo Comunale* hacia las 13:30. Recorrer las salas históricas y contemplar la célebre *Secchia Rapita*. Duración: 30 min. Entrada gratuita los sábados, con reserva obligatoria.\n*3.* Subir a la *Torre Ghirlandina* en la franja prevista de las 14:15. Recorrer sus salas históricas hasta la *Sala dei Torresani* (aprox. 200 escalones). Entrada €6 (≈ $122 MXN); reserva horaria obligatoria. No se permite acceder a la cima.\n*4.* Visitar opcionalmente los *Musei del Duomo* (15:15 aprox.) para conocer las esculturas originales y la historia del conjunto UNESCO. Duración: 30–40 min. Entrada €6 (≈ $122 MXN), con acceso incluido al presbiterio y sacristía del Duomo.\n*5.* Disfrutar del tiempo restante en *Piazza Grande* y las calles del centro antes de regresar a la estación. La *Galleria Estense* queda como alternativa al museo automovilístico, no como visita adicional obligatoria.",
          "night": "*1.* Caminar desde *Piazza Grande* hasta la estación *Modena* (20–25 min). Llegar con al menos 15 min de anticipación.\n*2.* Tomar el tren *Regionale* previsto a las 17:52 hacia *Bologna Centrale*. Confirmar el horario definitivo.\n*3.* Cenar cerca del alojamiento y regresar a *HouSmart Milazzo 5* para descansar.",
          "mobility": "• *Bologna → Modena:* Tren *Regionale* desde *Bologna Centrale*. Confirmar horario y tarifa en *Trenitalia*.\n• *Estación → Museo Enzo Ferrari:* Caminar 8–10 min hasta *Via Paolo Ferrari 85*.\n• *Museo → Piazza Grande:* Caminar 15–20 min hacia el centro histórico.\n• *Duomo → Mercato Albinelli:* Caminar 3–5 min hasta *Via Luigi Albinelli 13*.\n• *Mercato → Palazzo Comunale:* Caminar aproximadamente 5 min hasta *Piazza Grande 16*.\n• *Palazzo Comunale → Ghirlandina:* Ambos monumentos están en el mismo conjunto monumental, a pocos pasos.\n• *Ghirlandina → Musei del Duomo:* Caminar 2–3 min hasta *Via Lanfranco*.\n• *Centro → Estación:* Caminar 20–25 min hasta *Modena*.\n• *Modena → Bologna:* Tren *Regionale* previsto a las 17:52. Confirmar servicio y horario.\n• *Transporte local:* Todo el recorrido principal es peatonal. No se requieren autobuses ni taxis.",
          "spend": null,
          "note": "• *Museo Enzo Ferrari:* Abierto de 09:30 a 18:00 en diciembre. Entrada individual €27; compra anticipada recomendable. La entrada no incluye el museo de *Maranello*.\n• *The Greatest Hits:* Exposición temporal confirmada hasta el 16/02/2027. Incluida en la visita al museo automovilístico.\n• *Mercato Albinelli:* Los sábados de invierno abre de 07:00 a 19:00, según el calendario publicado. Los restaurantes sirven almuerzos generalmente de 12:00 a 15:00.\n• *Duomo:* Visitas turísticas de lunes a sábado entre las 10:00 y las 17:00, salvo celebraciones. Acceso principal gratuito. Presbiterio y sacristía €3 adicionales.\n• *Palazzo Comunale:* Los sábados abre de 13:00 a 15:00, con entrada gratuita y reserva obligatoria. Horario objetivo 13:30, pendiente de confirmación. La visita dura 30 min.\n• *Torre Ghirlandina:* Abierta de 09:30 a 18:00 en invierno. Reservar preferentemente la franja de las 14:15 (€6). Aproximadamente 200 escalones; acceso permitido hasta la *Sala dei Torresani*, no hasta la cima.\n• *Musei del Duomo:* Abiertos los sábados de 10:00 a 14:00 y de 15:00 a 19:00. Entrada €6, incluye el presbiterio y la sacristía. Visita opcional si se mantiene el horario previsto.\n• *Acetaia Marchi:* No confirmada para el sábado 05/12. El productor limita las visitas ordinarias de sábado a abril–octubre y establece un mínimo de 2 personas. Solicitar autorización excepcional para una persona, horario y precio en *tours@acetaiamarchi.com*. Sólo incorporarla si existe confirmación escrita y se reorganizan las reservas del día.\n• *Acetaia Comunale:* Cerrada por restauración desde el 19/10/2026, sin fecha de reapertura confirmada. No incluirla como alternativa.\n• *Galleria Estense:* Alternativa cultural al *Museo Enzo Ferrari* (€8 ≈ $163 MXN). Abierta los sábados de 08:30 a 19:15. No añadirla al recorrido principal.\n• *Reservas prioritarias:* Confirmar primero *Palazzo Comunale* (13:30) y *Torre Ghirlandina* (14:15). Son horarios propuestos, no reservas realizadas.\n• *Regreso:* El tren de las 17:52 es provisional. Verificar el horario definitivo en *Trenitalia*.",
