          "places": [],
          "am": "*1.* Desayunar en *HouSmart Milazzo 5*, revisar el apartamento, recoger todas las pertenencias y realizar el check-out.\n*2.* Salir del alojamiento hacia las 08:30 y caminar 5–10 min hasta *Bologna Centrale*. Dirigirse al acceso del *Marconi Express* en el vestíbulo de *Via de’ Carracci*.\n*3.* Tomar el tren automático *Marconi Express* hacia el *Aeroporto Guglielmo Marconi (BLQ)*. Trayecto de 7–8 min; billete €12.80 (≈ $261 MXN). Se puede pagar directamente con tarjeta contactless en los torniquetes.\n*4.* Seguir el pasillo cubierto hasta la terminal, en la planta de salidas. Objetivo de llegada: 09:15–09:25, aproximadamente 3 h antes del vuelo.\n*5.* Realizar los trámites de Iberia, pasar el control de seguridad y localizar la puerta de embarque. Desayunar algo adicional o comprar comida para el viaje si queda tiempo.",
          "pm": "*1.* Tomar el vuelo *Bologna (BLQ) → Madrid (MAD)*, salida prevista a las 12:25. Operado por *Air Nostrum* para *Iberia*; confirmar número de vuelo y horario definitivo.\n*2.* Realizar la conexión en el *Aeropuerto Adolfo Suárez Madrid-Barajas*. Tiempo previsto: 1 h 55 min. Seguir las señales de conexiones hacia *T4S*, utilizar el tren automático interno y pasar el control de pasaportes de salida del espacio Schengen.\n*3.* Dirigirse directamente a la puerta asignada al vuelo *Iberia Madrid → Ciudad de México (MEX)*. Confirmar terminal y horario en las pantallas del aeropuerto. No salir a la zona pública ni recoger equipaje si ambos vuelos están emitidos en una misma reserva y el equipaje está documentado hasta México.\n*4.* Embarcar en el vuelo transatlántico hacia *CDMX*.",
          "night": "*1.* Llegar al *Aeropuerto Internacional de la Ciudad de México (MEX)* a las 22:10 del lunes 7 de diciembre, según el itinerario aéreo de referencia.\n*2.* Pasar el control migratorio, recoger equipaje documentado si corresponde y realizar los trámites aduaneros.\n*3.* Trasladarse a casa. Fin del viaje por *Milano*, *Emilia-Romagna* y *Firenze*.",
          "mobility": "• *Alojamiento → Bologna Centrale:* Caminar 5–10 min desde *HouSmart Milazzo 5* hasta el acceso del *Marconi Express* por *Via de’ Carracci*.\n• *Bologna Centrale → Aeropuerto BLQ:* Tomar *Marconi Express* (7–8 min de recorrido). Servicio habitual de 05:40 a 00:00, con frecuencias variables de 7–15 min.\n• *Estación aeroportuaria → Terminal:* Seguir el pasillo cubierto hasta la planta de salidas (5–10 min).\n• *Tiempo total previsto:* Reservar 45–60 min desde el alojamiento hasta la terminal, incluyendo caminatas y espera.\n• *Plan B:* Taxi directo desde *HouSmart Milazzo 5* hasta BLQ (20–30 min; estimado €25–35 ≈ $510–$714 MXN, sujeto a tráfico y suplementos).\n• *Conexión en Madrid:* Seguir las señales de conexiones *T4 → T4S*. Utilizar el tren automático interno y pasar el control de pasaportes. No abandonar la zona de tránsito.\n• *Aeropuerto MEX → Casa:* Traslado por cuenta propia según la terminal de llegada.",
          "spend": null,
          "note": "• *Vuelo:* Itinerario previsto BLQ 12:25 → MAD → MEX 22:10. Confirmar vuelos, terminales y horarios en la reserva definitiva de Iberia.\n• *Marconi Express:* Billete sencillo €12.80. Acceso en *Bologna Centrale* por el vestíbulo de *Via de’ Carracci*. Pago con tarjeta contactless o billete digital.\n• *Servicio aeroportuario:* Consultar posibles interrupciones del *Marconi Express* la víspera. En caso de suspensión, utilizar el transporte sustitutorio oficial si mantiene el margen previsto o tomar taxi.\n• *Llegada a BLQ:* Objetivo 09:15–09:25, aproximadamente 3 h antes de la salida. Evitar retrasar el check-out.\n• *Check-in:* Realizar check-in online de Iberia cuando esté disponible. Descargar ambas tarjetas de embarque y verificar la asignación de asientos.\n• *Conexión en Madrid:* Escala prevista de 1 h 55 min. El tránsito habitual entre T4 y T4S requiere tren automático y control de pasaportes. No programar actividades ni compras durante la conexión.\n• *Reserva aérea:* Priorizar ambos vuelos en un solo billete para contar con protección de conexión. Si son reservas separadas, la escala resulta arriesgada y requiere reconsideración.\n• *Equipaje:* Confirmar límites de cabina de Iberia y Air Nostrum. Llevar pasaporte, documentos, medicamentos y objetos de valor en el equipaje personal.\n• *Fin del viaje:* 7 de diciembre de 2026. Total: 12 días naturales y 8 días laborales. Los traslados aeroportuarios no forman parte del total de trenes interurbanos.",
