        "why": "Cinco bases conectan palacios, ciudades históricas y excursiones de día; la variedad exige madrugar y reservar las visitas principales.",
        "soloWhy": "España y Portugal tienen buena infraestructura turística y gran parte del recorrido es sencilla en tren o vuelo directo, aunque cinco bases y varios cambios requieren organización.",
        "weatherWhy": "La lluvia puede afectar especialmente Sintra, los miradores de Granada, Zamora y algunas visitas exteriores de Barcelona, pero la mayoría de los atractivos principales tiene alternativas interiores."
