      "local": "Desde el aeropuerto llegarás al centro de Múnich en el S-Bahn, la red de trenes suburbanos, en unos 40–50 minutos. Para las excursiones, el tren a Salzburgo tarda aproximadamente 1½–2 horas y el ICE, tren de alta velocidad, llega a Núremberg en unas 1–1¼ horas.\n\nPara Neuschwanstein puedes reservar una excursión desde Múnich o tomar un tren a Füssen y después un autobús hasta Hohenschwangau, el pueblo desde el que se sube al castillo. Por tu cuenta, calcula unas 2½–3 horas de transporte por sentido. Para subir a Zugspitze, viajarás primero a Garmisch-Partenkirchen y continuarás en tren de montaña o teleférico.",
      "climate": "En diciembre, Múnich suele tener temperaturas cercanas a −2–6 °C. En las montañas hará bastante más frío: necesitarás abrigo, guantes y calzado con buen agarre. Puede nevar, aunque no se puede asegurar que la ciudad esté cubierta de nieve.\n\nLos días son cortos, por lo que las excursiones comenzarán temprano. El mercado navideño de Marienplatz está previsto del 20 de noviembre al 24 de diciembre de 2026; sus luces y puestos serán parte del ambiente de tus tardes en la ciudad.",
      "solo": "Con tu nivel de inglés puedes desenvolverte en hoteles, restaurantes y las principales atracciones turísticas. No necesitas hablar alemán para disfrutar este recorrido.\n\nMúnich será tu base durante todo el viaje: dormirás en el mismo hotel y visitarás los alrededores mediante excursiones de un día. Para organizar los trayectos en tren puedes utilizar DB Navigator, la aplicación de los ferrocarriles alemanes, donde podrás consultar horarios y conexiones.\n\nPara visitar el castillo de Neuschwanstein, considera una excursión organizada desde Múnich. Tendrás resuelto el transporte y podrás seguir las explicaciones de un guía en inglés; antes de reservar, revisa si también incluye la entrada al castillo.\n\nEl itinerario intercala las excursiones más largas con días tranquilos en Múnich. Después de una jornada en los Alpes, tendrás tiempo para recorrer palacios, disfrutar los mercados navideños y descansar.",
