      "flight": "Ventana propuesta: salir de Ciudad de México (MEX) el sábado 4 de septiembre de 2027, llegar a Zúrich (ZRH) el domingo 5 y regresar a MEX el viernes 17. Busca ida y vuelta con una conexión europea en una misma reserva. Compara duración total, equipaje y margen de conexión. No hay vuelos ni precios confirmados para esas fechas.\n\nAl 4 de octubre de 2026, parte de septiembre de 2027 puede quedar fuera del calendario de venta de algunas aerolíneas. Espera a que se pueda cotizar también el regreso antes de fijar hoteles no reembolsables. El programa supone llegada a México el día 17; si el billete llega el 18, serán 15 días naturales.",
      "local": "Aeropuerto de Zúrich → Lucerna: aproximadamente 1–1¼ horas. Lucerna → Interlaken Ost: alrededor de 1 h 50 min en el Luzern–Interlaken Express; después, conexión a Lauterbrunnen. Calcula 2½–3 horas en total entre estaciones de ambas bases. Este sí es un trayecto panorámico dentro de la ruta.\n\nDesde Lauterbrunnen explorarás Wengen, Mürren y Grindelwald en tren y teleférico, regresando al mismo hotel. Oeschinensee exige la excursión más larga: reserva el día completo. Lauterbrunnen → Zermatt requiere unas 3–4 horas, y Zermatt → Zúrich unas 3½–4 horas, con conexiones. Son estimaciones para planear, no horarios confirmados de 2027.\n\nCompara Swiss Half Fare Card + billetes con Swiss Travel Pass y un pase regional para los días del Oberland. La Half Fare Card cuesta actualmente CHF 150 por un mes y reduce el precio de muchos transportes; no es un billete ilimitado. Revisa cobertura y precios de 2027 antes de decidir. No compres varios pases con coberturas duplicadas.",
      "climate": "La primera quincena de septiembre es mi ventana preferida para esta ruta: permite plantear lagos y caminatas de temporada cálida, después del pico vacacional de mediados de julio a mediados de agosto. Alternativa: finales de junio o primera mitad de julio de 2027, comprobando nieve residual en senderos altos. La elección es por temporada, no por una previsión del tiempo ni por una oferta de vuelos.\n\nEn septiembre todavía puede llover, nevar en altura o amanecer con niebla. Lleva capas, impermeable y calzado de senderismo con agarre. No se garantiza ver el Cervino ni reflejos en los lagos. El día libre del Oberland y el margen de Zermatt permiten mover excursiones según visibilidad.\n\nOeschinensee ya publica operación de verano del 24 de abril al 19 de septiembre de 2027. Aun así, apertura del teleférico no significa que todos los senderos estén habilitados. First, sus accesos y cada ruta a pie deben revisarse para 2027 y de nuevo antes de salir. En diciembre, los lagos y senderos de estas fotos no ofrecen la misma experiencia.",
      "solo": "Viaje fácil de organizar por libre con inglés B2, señalización ferroviaria y una maleta manejable. Las caminatas son opcionales y se pueden acortar: el ritmo se vuelve más activo el día de First y más largo el de Oeschinensee. No hace falta coche.\n\nLa base del Oberland será Lauterbrunnen, cerca de la estación: equilibra Wengen, Mürren y las salidas hacia otros valles. Dormir en Wengen es una alternativa con más ambiente de montaña, pero añade una subida en tren con la maleta y tiempo a las excursiones. Recalcula los traslados si cambias la base.",
