      "flight": "Cotiza una sola reserva multidestino, también llamada open-jaw: Ciudad de México (MEX) → Zúrich (ZRH) el 5 de diciembre y Milán Malpensa (MXP) → Ciudad de México (MEX) el 16. Compara conexiones en Frankfurt o Múnich y equipaje incluido.\n\nNo se encontró una tarifa reservable verificada para esta combinación exacta. El rango de $20,000–$32,000 MXN es una provisión para comparar, no una oferta. Exige llegada a MEX el 16 para conservar los ocho días laborales; aterrizar el 17 añadiría un día natural y laboral.",
      "local": "Hasta St. Moritz sigues la ruta original: Lucerna, Zermatt y Glacier Express. El 14 de diciembre toma un tren local temprano a Pontresina, donde abordarás el Bernina Express 951 de las 10:25 a Tirano, llegada 12:49.\n\nEn invierno ese servicio no parte de St. Moritz: la conexión local es necesaria. Desde Tirano continuarás en Trenord a Milano Centrale, unas 2½ horas. Deja al menos 60–90 minutos para enlazar sin correr; el horario italiano posterior al 13 de diciembre requiere confirmación.",
      "climate": "En diciembre, Lucerna puede rondar los 0–7 °C y las zonas de montaña registrar temperaturas bajo cero. Es más probable encontrar nieve en las cumbres y los pasos alpinos que en las calles de una ciudad.\n\nLas nubes pueden ocultar el Cervino o las vistas desde Gornergrat. Por eso hay días de margen en Zermatt: podrás escoger la jornada más despejada para subir al mirador.",
      "solo": "La señalización de las estaciones y el uso habitual del inglés en servicios turísticos hacen que Suiza sea cómoda para viajar solo. Los trayectos están pensados para disfrutar del paisaje, aunque deberás cargar tu equipaje al cambiar de tren.\n\nUna maleta manejable hará mucha diferencia. También conviene planear con cuidado el presupuesto: alojamiento, comidas y transportes de montaña representan una parte importante del coste total.",
