      "flight": "Volarás de Ciudad de México (MEX) a Atenas, al aeropuerto Eleftherios Venizelos (ATH), cambiando de avión en una ciudad europea como Madrid, París, Frankfurt o Ámsterdam.\n\nCompra los trayectos de cada sentido dentro de una misma reserva. Así la aerolínea podrá gestionar la conexión si un retraso afecta al siguiente vuelo, de acuerdo con las condiciones del billete. El regreso saldrá de Atenas y tendrá una conexión antes de llegar a México.",
      "local": "Entre Atenas y Nafplio puedes utilizar los autobuses interurbanos de KTEL; el trayecto suele ocupar unas 2–2½ horas.\n\nEl día más largo será el traslado de Nafplio a Meteora. En transporte público puede requerir pasar de nuevo por Atenas y sumar unas 7–9 horas, incluidas las esperas. Un traslado contratado puede simplificar el recorrido, aunque encarece el viaje.\n\nPara volver de Meteora a Atenas, calcula unas 4½–6 horas según el servicio disponible. Habrá que comprobar si se realiza en autobús o combinando tren y autobús; el plan no depende de que exista un tren directo.",
      "climate": "Atenas puede tener temperaturas cercanas a 9–17 °C. En Meteora hará más frío y puede haber niebla, especialmente a primeras horas.\n\nLos yacimientos arqueológicos suelen tener jornadas de visita más cortas en invierno. Dedicaremos las mañanas a los templos y ruinas, y dejaremos las tardes para museos, cafés o paseos breves.",
      "solo": "Atenas resulta cómoda para viajar solo y puedes comunicarte en inglés en los principales servicios turísticos. Las excursiones rurales necesitan algo más de preparación porque hay menos frecuencias de autobús y cada monasterio tiene sus propios días de apertura.\n\nEn Meteora, una excursión local con transporte permite disfrutar de los miradores y visitar dos monasterios sin resolver cada desplazamiento por tu cuenta. Los días adicionales sirven para descansar o recuperar una visita si la niebla impide apreciar el paisaje.",
