      "local": "El cambio de Palermo a Catania se hará en autobús interurbano, con una duración orientativa de 2½–3½ horas.\n\nDesde Catania, calcula aproximadamente 1–1½ horas para llegar a Siracusa, 1½–2 horas a Noto y 1–1½ horas a Taormina, según el servicio. Si eliges tren para Taormina, necesitarás además subir desde la estación hasta el centro histórico.\n\nAgrigento será la excursión más larga desde Palermo: unas 2–2½ horas por sentido, más el traslado al Valle de los Templos. Reservar una excursión con recogida puede hacer más sencillo ese día.",
