      "intro": "Las Vegas combina hoteles de fantasía, espectáculos nocturnos y paisajes del desierto. Dormirás cinco noches en el mismo hotel y realizarás excursiones a Hoover Dam y al borde sur del Grand Canyon. La salida al cañón será larga; el día siguiente queda más ligero para que puedas recuperarte.",
      "bases": [
        [
          "Las Vegas",
          5
        ]
      ],
      "flight": "Busca un vuelo sin escalas de Ciudad de México (MEX) al aeropuerto Harry Reid de Las Vegas (LAS), con Aeroméxico o Volaris según las fechas disponibles. El regreso puede hacerse por la misma ruta.\n\nEl aeropuerto está cerca de la zona de hoteles del Strip. El traslado suele ocupar unos 15–30 minutos en coche, dependiendo del tráfico y del hotel elegido.",
      "local": "El Strip es la avenida de los grandes hoteles. Puedes recorrer a pie una zona por vez y utilizar el monorraíl o un vehículo por aplicación para las distancias largas.\n\nLa visita a Hoover Dam, la presa del río Colorado, ocupa unas 4–6 horas en excursión organizada. El Grand Canyon South Rim, o borde sur del parque nacional, queda mucho más lejos: unas 4½–5½ horas de carretera por sentido y una jornada total de 14–16 horas.\n\nGrand Canyon West está más cerca de Vegas, pero es un destino distinto, con otras vistas y entradas. Esta propuesta se refiere al parque nacional y su borde sur.",
      "climate": "En diciembre, Las Vegas puede rondar los 4–15 °C. En el Grand Canyon South Rim hará más frío y puede haber nieve o hielo.\n\nAntes de la excursión al cañón, el operador deberá comprobar las carreteras y los accesos. Lleva ropa de abrigo aunque la tarde anterior en Las Vegas haya sido templada.",
      "solo": "Es fácil viajar solo con inglés y contratar excursiones compartidas. Un hotel bien ubicado te ayudará a combinar paseos y espectáculos con menos desplazamientos.\n\nLos tours privados y la habitación individual elevan el coste. Para este viaje, las excursiones en grupo suelen ser más razonables; también conviene dejar libre la mañana posterior al Grand Canyon para descansar.",
