      "flight": "Busca un vuelo de Ciudad de México (MEX) a Marrakech-Menara (RAK), con conexión europea, normalmente en Madrid o París. Algunas combinaciones requieren dos cambios de avión; compara el tiempo total y no sólo el precio.\n\nPara regresar desde Essaouira, la propuesta principal es un traslado por carretera al aeropuerto de Marrakech y un vuelo por la tarde. Si el vuelo sale temprano, conviene añadir una noche final en Marrakech. También se puede comparar el aeropuerto de Essaouira (ESU), aunque sus conexiones deben encajar realmente con el viaje a México.",
      "local": "El autobús entre Marrakech y Essaouira tarda unas tres horas; un traslado privado suele ocupar aproximadamente 2½–3 horas. Será el único cambio de ciudad con equipaje durante la estancia.\n\nAgafay está a unos 45–60 minutos de Marrakech por carretera y se puede visitar durante una tarde, regresando al mismo alojamiento. El Sahara queda demasiado lejos para plantearlo como una excursión cómoda de un día desde Marrakech.",
      "climate": "A finales de noviembre, Marrakech puede tener temperaturas de unos 10–22 °C. Las tardes suelen permitir paseos agradables, pero refresca al caer el sol.\n\nEn Essaouira puede soplar bastante viento junto al mar. Para Agafay lleva una prenda de abrigo: la cena y el regreso se realizarán después del atardecer.",
      "solo": "Viajar solo requiere algo más de preparación que en las rutas europeas. Para tu primera visita a la medina, el centro histórico de calles estrechas, conviene contratar un guía acreditado que te ayude a orientarte.\n\nUn riad es una casa tradicional organizada alrededor de un patio, muchas veces convertida en alojamiento. Elige uno que explique bien cómo llegar y ofrezca recogida si el taxi no puede acceder a su calle. Reserva los traslados con antelación y acuerda el precio de cualquier servicio antes de aceptarlo.",
