      "climate": "En diciembre, las temperaturas pueden situarse aproximadamente entre 7 y 19 °C, aunque un frente frío puede hacerlas bajar. Lleva una chaqueta y comprueba el pronóstico antes de salir.\n\nLa iluminación de temporada añade atractivo a los paseos por el río. Las caminatas más largas se pueden reservar para las horas centrales del día.",
