      "flight": "Salida desde Ciudad de México (MEX) el 18 de septiembre de 2027 hacia Bari (BRI), buscando una sola conexión en una misma reserva. Llegada prevista el 19; regreso desde Bari el 28, también con una conexión. No se añaden visitas ni hotel en Roma u otra ciudad de enlace.\n\nSeptiembre de 2027 es una propuesta: no se consideran confirmados vuelos, tarifas ni horarios de transporte. Cuando abra la venta, compara conexiones que permitan llegar a Matera sin prisas. Confirma que el regreso aterrice en MEX el 28 para mantener los siete días laborales.",
