      "climate": "Septiembre permite dedicar tiempo a la costa y a los paseos al aire libre, aunque aún puede hacer calor y también llover. Lleva protección solar, agua y calzado con buen agarre para la piedra y las escaleras.\n\nEn Matera aprovecha las primeras y últimas horas del día. La costa puede tener viento o mar agitado: el programa se basa en miradores y pueblos, no depende de bañarse ni de una salida en barco.",
